    desc: '看 API 回應的好幫手：可收合的 JSON 樹，鍵、字串、數字、布林與 null 沿用程式碼區塊的 --ml-code-* 配色。收合的節點顯示「{…} 12 個鍵」「[…] 30 項」，長字串截斷可展開，大陣列每次顯示 100 項；搜尋會標出符合的鍵與值並自動展開路徑。點鍵名複製路徑（$.users[3].name 或 users.3.name），點值複製內容，成功時蓋上獅掌。http(s) 網址變成連結、ISO 日期變成 <time>，循環參照不會當掉，原始字串格式錯誤時指出第幾行第幾欄。完全不用 v-html。',
