    desc: '鋼鐵風控制列的影片播放器，底層還是原生 <video>，所以格式支援、串流與字幕都交給瀏覽器。有進度條（含已緩衝範圍）、音量、播放速度選單、字幕選單、子母畫面（瀏覽器支援時才出現）和全螢幕；播放中滑鼠不動會自動隱藏控制列。鍵盤操作與 YouTube 相同：空白鍵或 K 播放、← → 前後 5 秒、J / L 前後 10 秒、↑ ↓ 音量、M 靜音、F 全螢幕、C 字幕、0–9 跳到 0–90%、Shift + < > 調速度。',
